def part(pid,name,path,sheet,rows,decision,vids,producers=(),consumers=(),up=(),history=(),scope='',limits='',errors=(),fields=None,header=4,selection=None,components=()):
    e=obj(path);sub={'sheet':sheet,'row_count':rows}
    if sheet:
        hh,sh=headers(path,sheet,header)
        selected={c:v for c,v in hh.items() if fields is None or v in fields}
        sub.update({'header_row':header,'range':selection or f'{next(iter(hh))}{header}:{list(hh)[-1]}{sh["last_row"]}','columns':selected,'field_selection_is_exhaustive':True,'xml_member':sh['xml_member'],'all_sheet_field_count':len(hh)})
    else:sub['selector']=selection or 'whole file'
    vals=[]
    for v in vids:
        if v in VAL:
            r=VAL[v];vals.append({'validation_id':v,'receipt_path':str(OUT/'core_validation.jsonl'),'line':r['receipt_line'],'status':r['status'],'scope':r.get('boundary',r.get('validation_boundary','see exact receipt'))})
        else:vals.append({'receipt_path':str(OUT.parent/'main'/v),'scope':'parent common image-visual receipt; not reverse candidate conclusion'})
    p={'local_part_id':pid,'name':name,'source_path':e.pop('path'),'sha256':e.pop('sha256'),'source_identity':e,'subobject':sub,'kind':'COMPOSITE_SHEET_FIELD_GROUP' if sheet else 'FILE_OR_JSON_SUBOBJECT','decision':decision,'recommendation_only':True,'components':list(components),'capability_scope':scope,'upstream_paths':[obj(x) for x in up],'producers':[pref(x) for x in producers],'consumer_paths':[pref(x) for x in consumers],'pre_chat_refs':chat(history),'validation_refs':vals,'known_errors':list(errors),'version_adjudication':{'family':'later 输出_新版 / numbered M successor, not rejected 输出/','pre_history_basis':'listed original PRE chat pointers and inspected producer/consumer IO; mtime not used','current_byte_binding':'00A identity PASS; raw input hashes and record hashes compared where validation receipt says so','historical_consumer_input_sha_binding':'Only established where quoted receipt embeds the input SHA; no uninspected historical manifest is asserted','successor_scope':'new136 replaces old131 manual numbering; M0/M1 migrate scope while retaining stable position_cycle_id; field-level errors do not invalidate unrelated verified fields'},'user_rejection':{'rejected_output_branch':['W01-M0284-U:48273','W01-M0322-U:52341'],'effect':'old 输出/ rejected, not blanket rejection of later 输出_新版','manual_replacement':'W04-M0130-U:14224-14243; only new136 manual replaces old131 authority'},'samebytes':{'current_00A_hash_aliases':[str(ROOT/x) for x in HASHES[ENTRIES[path]['sha256']] if x!=path],'meaning':'current byte aliases only, not historical adoption proof'},'limits':limits,'discovered_via':'INDEPENDENT_SUPPLY_FORWARD_RAW_TO_CONSUMER','independence_snapshot':str(OUT/'independent_supply_candidates_manifest.json'),'authority_and_acceptance':'parent must independently adjudicate; no formal file copied/extracted or promoted in this delivery'}

