applied_generator.source_code:
// Pure, fail-closed replacement for alias-prefix and cross-field fallbacks.
// No filesystem, network, model, business algorithm, or publication side effects.
// A caller must supply ROOT-ADJUDICATED decisions. This module validates binding
// and projects approved text; it does not invent or semantically approve reasons.
import {isDeepStrictEqual} from 'node:util';

export class ReasonBindingError extends Error {
  constructor(code, detail) {
    super(code+': '+detail);
    this.name='ReasonBindingError';
    this.code=code;
  }
}
const fail=(code,detail)=>{throw new ReasonBindingError(code,detail);};
const text=(v,key,id)=>{
  if(typeof v!=='string'||v.trim()==='')fail('EXPLICIT_REASON_FIELD_REQUIRED',id+' '+key);
  return v;
};
const clone=x=>structuredClone(x);
const closedOutcomes=new Set([
  'CORRESPONDENCE_CONFIRMED_AS_IS',
  'REASON_TEXT_CONTAMINATED_ACTION_UNCHANGED',
  'REASON_AND_VALIDATION_SCOPE_CONTAMINATED',
  'REUSE_ACTION_REQUIRES_REASSESSMENT'
]);
const actions=new Set([
  'COPY_FILE_AS_IS_AFTER_USER_ACCEPTANCE',
  'EXTRACT_SUBOBJECT_AFTER_USER_ACCEPTANCE',
  'RECOMPUTE_FROM_AUTHORITY_IN_CLEAN_PRODUCTION',
  'REFERENCE_ONLY',
  'PROHIBITED_FOR_FORWARD_BUILD',
  'NO_PREK01_REUSABLE_PART_FOUND'
]);
const same=(actual,expected,key,id)=>{
  if(!isDeepStrictEqual(actual,expected))fail('REASON_BINDING_IDENTITY_MISMATCH',id+' '+key);
};

export function partBinding(part) {
  for(const key of ['part_id','name','source_path','source_file_sha256']){
    if(typeof part[key]!=='string'||!part[key].trim())fail('INCOMPLETE_PART_IDENTITY',String(part.part_id)+' '+key);
  }
  if(!/^[a-f0-9]{64}$/i.test(part.source_file_sha256))fail('INCOMPLETE_PART_IDENTITY',part.part_id+' SHA256');
  if(!part.subobject||typeof part.subobject!=='object'||Array.isArray(part.subobject))fail('INCOMPLETE_PART_IDENTITY',part.part_id+' selector');
  for(const key of ['local_aliases','producer_process_ids','consumer_process_ids','source_record_refs']){
    if(!Array.isArray(part[key]))fail('INCOMPLETE_PART_IDENTITY',part.part_id+' '+key);
  }
  if(!part.local_aliases.length||!part.source_record_refs.length)fail('INCOMPLETE_PART_IDENTITY',part.part_id+' aliases/source refs');
  if(part.source_record_refs.some(r=>typeof r.file!=='string'||!r.file||typeof r.local_part_id!=='string'||!r.local_part_id))fail('INCOMPLETE_PART_IDENTITY',part.part_id+' source ref fields');
  return clone({
    part_id:part.part_id,
    name:part.name,
    source_path:part.source_path,
    source_file_sha256:part.source_file_sha256,
    subobject:part.subobject,
    local_aliases:part.local_aliases,
    producer_process_ids:part.producer_process_ids,
    consumer_process_ids:part.consumer_process_ids,
    source_record_refs:part.source_record_refs
  });
}

// This adapter enumerates heterogeneous historical advice but deliberately does
// NOT promote a version rationale, scope enum, or first alias into a root reason.
export function collectSourceReasonCandidates(recommendation) {
  return ['root_decision_reason','decision_reason','reuse_reason','reason']
    .filter(field=>typeof recommendation[field]==='string'&&recommendation[field].trim())
    .map(field=>({field,text:recommendation[field]}));
}

export function sourceBinding(recommendation, sourceFile) {
  return clone({
    source_file:sourceFile,
    local_part_id:recommendation.local_part_id,
    source_path:recommendation.source_path,
    source_file_sha256:recommendation.sha256??recommendation.file_sha256,
    subobject:recommendation.subobject
  });
}

// Use instead of scoped()'s startsWith('MECH-EXTRA-') branch. The caller decides
// whether an exact source record has an approved override. No matching record is
// a no-op here; a later complete decision registry is mandatory before projection.
export function applyExactSourceOverride(recommendation, sourceFile, overrides) {
  const key=sourceFile+'\u0000'+recommendation.local_part_id;
  const matches=overrides.filter(o=>o.source_key===key);
  if(matches.length>1)fail('DUPLICATE_SOURCE_OVERRIDE',key);
  const out=clone(recommendation);
  if(matches.length===0)return out;
  const d=matches[0];
  same(sourceBinding(recommendation,sourceFile),d.expected_source_binding,'source binding',key);
  if(d.resolution!=='RESOLVED')fail('UNRESOLVED_SOURCE_OVERRIDE',key);
  out.root_decision_reason=text(d.root_decision_reason,'root_decision_reason',key);
  if(Object.hasOwn(d,'component_ids')){
    if(!Array.isArray(d.component_ids))fail('EXPLICIT_COMPONENT_DECISION_REQUIRED',key);
    out.components=clone(d.component_ids);
  }
  out.reason_source_override_id=text(d.decision_id,'decision_id',key);
  return out;
}

export function buildDecisionRegistry(parts, decisions, expectedCount=294) {
  if(parts.length!==expectedCount)fail('PART_DENOMINATOR_MISMATCH',String(parts.length));
  const ids=new Set(parts.map(p=>p.part_id));
  if(ids.size!==parts.length)fail('DUPLICATE_PART_ID','part universe');
  const map=new Map();
  for(const d of decisions){
    if(!ids.has(d.part_id))fail('OUT_OF_SCOPE_REASON_DECISION',String(d.part_id));
    if(map.has(d.part_id))fail('DUPLICATE_PART_REASON_DECISION',d.part_id);
    map.set(d.part_id,d);
  }
  if(map.size!==ids.size)fail('REASON_CORRESPONDENCE_NOT_CLOSED',`${map.size}/${ids.size}`);
  return map;
}

function validateReferents(part, decision, universe) {
  const referred=decision.referent_part_ids??[];
  if(!Array.isArray(referred)||new Set(referred).size!==referred.length)fail('INVALID_REFERENT_LIST',part.part_id);
  for(const id of referred)if(!universe.has(id))fail('UNRESOLVED_REASON_REFERENT',part.part_id+' '+id);
  const combined=decision.root_decision_reason+'\n'+decision.selected_data_validation_scope;
  const fields=decision.field_referents??[];
  if(!Array.isArray(fields))fail('INVALID_FIELD_REFERENTS',part.part_id);
  for(const f of fields){
    if(!f||typeof f!=='object'||Array.isArray(f))fail('INVALID_FIELD_REFERENT',part.part_id);
    for(const key of ['referent_text','source_field','interpretation']){
      if(typeof f[key]!=='string'||!f[key].trim())fail('INCOMPLETE_FIELD_REFERENT',part.part_id+' '+key);
    }
    if(!hasNonemptyEvidence(f.evidence_refs))fail('FIELD_REFERENT_EVIDENCE_REQUIRED',part.part_id+' '+f.referent_text);
    if(!combined.includes(f.referent_text))fail('FIELD_REFERENT_TEXT_NOT_PRESENT',part.part_id+' '+f.referent_text);
  }
  const deictics=[...new Set(combined.match(/这两份|这两项|前者|后者/g)??[])];
  for(const token of deictics){
    if(referred.length>=2)continue;
    // Two files still require two BP endpoints. Other deictics may refer to
    // methods or fields within this exact object, without inventing extra BPs.
    const fieldResolved=token!=='这两份'&&fields.some(f=>f.referent_text.includes(token));
    if(!fieldResolved)fail('UNRESOLVED_DEICTIC_REASON',part.part_id+' '+token);
  }
  return referred;
}

function hasNonemptyEvidence(refs) {
  const nonempty=v=>typeof v==='string'?v.trim().length>0:
    !!v&&typeof v==='object'&&(Array.isArray(v)?v.length>0&&v.every(nonempty):Object.values(v).some(nonempty));
  return Array.isArray(refs)&&refs.length>0&&refs.every(nonempty);
}

function projectCurrentScope(part, decision, selectedScope) {
  const prior=part.current_scope_validation;
  let value=clone(prior),mode='UNCHANGED_CURRENT_SCOPE';
  let evidence=[];
  if(Object.hasOwn(decision,'current_scope_validation_override')){
    if(decision.scope_override_authorized!==true)fail('CURRENT_SCOPE_OVERRIDE_NOT_AUTHORIZED',part.part_id);
    if(!hasNonemptyEvidence(decision.scope_override_evidence_refs))fail('CURRENT_SCOPE_OVERRIDE_EVIDENCE_REQUIRED',part.part_id);
    const override=decision.current_scope_validation_override;
    if(override!==null)text(override,'current_scope_validation_override',part.part_id);
    value=clone(override);mode='EXPLICIT_ROOT_AUTHORIZED_CURRENT_SCOPE_OVERRIDE';evidence=clone(decision.scope_override_evidence_refs);
  }else if(prior!=null&&['COPY_FILE_AS_IS_AFTER_USER_ACCEPTANCE','EXTRACT_SUBOBJECT_AFTER_USER_ACCEPTANCE'].includes(part.reuse_action)){
    // Synchronize wording only where a selected scope already existed. This
    // does not create validation for REFERENCE/PROHIBITED/RECOMPUTE objects.
    value=selectedScope;
    if(!isDeepStrictEqual(value,prior)){
      mode='SYNCHRONIZED_EXISTING_SELECTED_SCOPE_TEXT';evidence=clone(decision.evidence_refs);
    }
  }else if(prior==null){
    mode='NULL_OR_ABSENT_CURRENT_SCOPE_PRESERVED';
  }
  return {value,audit:{mode,prior_current_scope_validation:clone(prior),current_scope_validation:clone(value),evidence_refs:evidence,proof_boundary:'RETAINED_VALIDATION_BOUNDARY_CORRESPONDENCE_CORRECTION_ONLY_NOT_NEW_BUSINESS_VALIDATION',new_business_validation_performed:false,validation_status_changed_by_this_projection:false}};
}

function validateExclusiveQuantities(part, decision, universe, contracts) {
  const combined=decision.root_decision_reason+'\n'+decision.selected_data_validation_scope;
  const bindings=decision.quantity_bindings??[];
  const related=new Set([part.part_id,...(decision.referent_part_ids??[])]);
  const tokens=[...new Set(contracts.map(c=>c.token))];
  for(const token of tokens){
    if(!combined.includes(token))continue;
    const hit=bindings.filter(b=>b.token===token);
    if(hit.length===0)fail('EXCLUSIVE_QUANTITY_BINDING_REQUIRED',part.part_id+' '+token);
    for(const b of hit){
      const candidates=contracts.filter(c=>c.token===token&&(!b.quantity_contract_id||c.quantity_contract_id===b.quantity_contract_id));
      if(candidates.length!==1)fail('AMBIGUOUS_QUANTITY_CONTRACT',part.part_id+' '+token);
      const contract=candidates[0];
      same(b.subject_part_id,contract.subject_part_id,'quantity subject',part.part_id);
      same(b.source_locator,contract.source_locator,'quantity locator',part.part_id);
      if(contract.quantity_kind)same(b.quantity_kind,contract.quantity_kind,'quantity semantic kind',part.part_id);
      if(!related.has(b.subject_part_id))fail('CROSS_OBJECT_QUANTITY_NOT_REFERENCED',part.part_id+' '+token);
      if(!universe.has(b.subject_part_id))fail('MISSING_QUANTITY_SUBJECT',part.part_id+' '+token);
      same(partBinding(universe.get(b.subject_part_id)),contract.expected_subject_binding,'quantity subject identity',part.part_id);
      // Kind can distinguish OBJECT_ROWS, AUXILIARY_GROUPED_IDS, UPSTREAM_ROWS,
      // or FAMILY_TOTAL. Never equate a family/upstream count to the current
      // part's row count, and never rewrite either value to make them agree.
      // Object references alone are not proof of a business relation. A non-self
      // reference must carry a root-reviewed retained-evidence locator.
      if(b.subject_part_id!==part.part_id&&!(b.relationship_evidence_refs?.length))fail('CROSS_OBJECT_QUANTITY_RELATION_UNPROVEN',part.part_id+' '+token);
    }
  }
}

export function resolvePartReason(part, registry, universe, quantityContracts=[]) {
  const decision=registry.get(part.part_id);
  if(!decision)fail('MISSING_BOUND_REASON_DECISION',part.part_id);
  if(decision.resolution!=='RESOLVED'||!closedOutcomes.has(decision.outcome))fail('BUSINESS_REASON_CORRESPONDENCE_UNRESOLVED',part.part_id);
  if(decision.outcome==='REUSE_ACTION_REQUIRES_REASSESSMENT'&&decision.action_reassessment_closed!==true)fail('REUSE_ACTION_REASSESSMENT_UNCLOSED',part.part_id);
  same(partBinding(part),decision.expected_binding,'part binding',part.part_id);
  const reason=text(decision.root_decision_reason,'root_decision_reason',part.part_id);
  const scope=text(decision.selected_data_validation_scope,'selected_data_validation_scope',part.part_id);
  const id=text(decision.decision_id,'decision_id',part.part_id);
  if(!actions.has(decision.reuse_action))fail('INVALID_REUSE_ACTION',part.part_id);
  if(!Array.isArray(decision.evidence_refs)||!decision.evidence_refs.length)fail('REASON_EVIDENCE_REQUIRED',part.part_id);
  if(!Array.isArray(decision.component_ids))fail('EXPLICIT_COMPONENT_DECISION_REQUIRED',part.part_id);
  const actionChanged=decision.reuse_action!==part.reuse_action;
  const componentsChanged=!isDeepStrictEqual(decision.component_ids,part.component_ids);
  if(actionChanged&&decision.action_reassessment_closed!==true)fail('ACTION_CHANGE_NOT_ADJUDICATED',part.part_id);
  if(componentsChanged&&decision.component_reassessment_closed!==true)fail('COMPONENT_CHANGE_NOT_ADJUDICATED',part.part_id);
  validateReferents(part,decision,universe);
  validateExclusiveQuantities(part,decision,universe,quantityContracts);
  const currentScope=projectCurrentScope(part,decision,scope);
  const binding={decision_id:id,part_id:part.part_id,expected_binding:clone(decision.expected_binding),evidence_refs:clone(decision.evidence_refs),referent_part_ids:clone(decision.referent_part_ids??[]),field_referents:clone(decision.field_referents??[]),quantity_bindings:clone(decision.quantity_bindings??[])};
  const partFields={root_decision_reason:reason,current_scope_validation:currentScope.value,component_ids:clone(decision.component_ids),reuse_action:decision.reuse_action,reason_correspondence_id:id,reason_correspondence_audit:{record_type:'BUILD_PART_REASON_CORRESPONDENCE_AUDIT',...clone(decision.audit??{}),...binding,outcome:decision.outcome,resolution:decision.resolution,root_decision_reason:reason,selected_data_validation_scope:scope,current_scope_validation_projection:currentScope.audit,reuse_action:decision.reuse_action,component_ids:clone(decision.component_ids)}};
  const cardFields={root_reason:reason,ai_checked:scope,reuse_action:decision.reuse_action,reason_correspondence_id:id};
  const versionFields={};
  if(Object.hasOwn(decision,'version_adjudication')){
    if(decision.version_adjudication==null||(typeof decision.version_adjudication==='string'&&!decision.version_adjudication.trim()))fail('EXPLICIT_VERSION_RATIONALE_REQUIRED',part.part_id);
    partFields.version_adjudication=clone(decision.version_adjudication);
    versionFields.current_version_rationale=clone(decision.version_adjudication);
    versionFields.prior_advice_status='HISTORICAL_RECOMMENDATION_NOT_CURRENT_OBJECT_CONCLUSION';
    versionFields.reason_correspondence_id=id;
    // prior_advice, selected_sha256, source_path and subobject intentionally absent.
    // The old recommendation and selected version identity must remain untouched.
  }
  if(Object.hasOwn(decision,'card_plain_interpretation'))cardFields.plain_interpretation=text(decision.card_plain_interpretation,'card_plain_interpretation',part.part_id);
  if(Object.hasOwn(decision,'card_version_current_meaning'))cardFields.version_current_meaning=clone(decision.card_version_current_meaning);
  // No reason->scope, version->reason, prefix->reason, or first-alias fallback.
  return {
    part_id:part.part_id,
    part_fields:partFields,
    reuse_fields:{root_decision:reason,selected_data_validation_scope:scope,reuse_action:decision.reuse_action,reason_correspondence_id:id},
    card_fields:cardFields,
    version_fields:versionFields,
    binding
  };
}

export function resolveAllReasonProjections(parts, decisions, options={}) {
  const registry=buildDecisionRegistry(parts,decisions,options.expectedCount??294);
  const universe=new Map(parts.map(p=>[p.part_id,p]));
  // Validate the complete universe before returning any publishable projection.
  return parts.map(p=>resolvePartReason(p,registry,universe,options.quantityContracts??[]));
}

