def build_minute_index(path):
    result = {}
    with path.open("r", encoding="utf-8-sig", newline="") as handle:
        for raw in csv.DictReader(handle):
            key = (raw["symbol"], int(raw["open_time_ms"]))
            if key in result:
                raise RuntimeError(f"Independent path duplicate minute: {key}")
            result[key] = raw
    return result


